import{_ as t,o as e,f as i,a6 as l}from"./chunks/framework.BFhbG0o2.js";const p=JSON.parse('{"title":"Stable Diffusion LoRA 模型包","description":"","frontmatter":{"title":"Stable Diffusion LoRA 模型包","pageClass":"page-resource-detail","status":"draft","search":false,"layout":"page"},"headers":[],"relativePath":"resources/lora.md","filePath":"resources/lora.md"}'),r={name:"resources/lora.md"};function o(s,a,d,n,h,c){return e(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="stable-diffusion-lora-模型包" tabindex="-1">Stable Diffusion LoRA 模型包 <a class="header-anchor" href="#stable-diffusion-lora-模型包" aria-label="Permalink to &quot;Stable Diffusion LoRA 模型包&quot;">​</a></h1><h2 id="模型介绍" tabindex="-1">模型介绍 <a class="header-anchor" href="#模型介绍" aria-label="Permalink to &quot;模型介绍&quot;">​</a></h2><p>通用人像模型包，专为生成高质量人像设计，包含10+精选 LoRA 模型。</p><h3 id="模型特点" tabindex="-1">模型特点 <a class="header-anchor" href="#模型特点" aria-label="Permalink to &quot;模型特点&quot;">​</a></h3><ul><li>👤 真实人像风格</li><li>🎭 多种表情姿态</li><li>🌈 丰富的场景适配</li><li>⚡ 快速训练收敛</li></ul><h2 id="模型列表" tabindex="-1">模型列表 <a class="header-anchor" href="#模型列表" aria-label="Permalink to &quot;模型列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模型名称</th><th>风格</th><th>适用场景</th><th>权重建议</th></tr></thead><tbody><tr><td>Realistic Portrait</td><td>写实</td><td>证件照、职业照</td><td>0.7-0.9</td></tr><tr><td>Anime Character</td><td>二次元</td><td>角色设计</td><td>0.6-0.8</td></tr><tr><td>Studio Light</td><td>影棚光效</td><td>商业摄影</td><td>0.5-0.7</td></tr><tr><td>Natural Beauty</td><td>自然美颜</td><td>日常人像</td><td>0.6-0.8</td></tr></tbody></table><h2 id="下载说明" tabindex="-1">下载说明 <a class="header-anchor" href="#下载说明" aria-label="Permalink to &quot;下载说明&quot;">​</a></h2><p><strong>完整模型包：</strong> 来源与授权仍在核实，暂不提供下载。</p><p><strong>单个模型下载</strong>：访问 <a href="https://civitai.com/" target="_blank" rel="noreferrer">CivitAI</a> 搜索对应模型名称</p><h2 id="使用教程" tabindex="-1">使用教程 <a class="header-anchor" href="#使用教程" aria-label="Permalink to &quot;使用教程&quot;">​</a></h2><h3 id="安装步骤" tabindex="-1">安装步骤 <a class="header-anchor" href="#安装步骤" aria-label="Permalink to &quot;安装步骤&quot;">​</a></h3><ol><li>下载模型包并解压</li><li>将 <code>.safetensors</code> 文件复制到 <code>stable-diffusion-webui/models/Lora/</code> 目录</li><li>重启 WebUI 界面</li></ol><h3 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法&quot;">​</a></h3><p>在提示词中使用 LoRA：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>beautiful woman portrait &lt;lora:Realistic_Portrait:0.8&gt;, </span></span>
<span class="line"><span>professional lighting, studio background, 8k, detailed</span></span></code></pre></div><h3 id="参数建议" tabindex="-1">参数建议 <a class="header-anchor" href="#参数建议" aria-label="Permalink to &quot;参数建议&quot;">​</a></h3><ul><li><strong>采样步数</strong>：20-30</li><li><strong>CFG Scale</strong>：7-9</li><li><strong>LoRA 权重</strong>：0.6-0.9</li><li><strong>分辨率</strong>：512x768 或 768x1024</li></ul><h2 id="示例效果" tabindex="-1">示例效果 <a class="header-anchor" href="#示例效果" aria-label="Permalink to &quot;示例效果&quot;">​</a></h2><p>采用 <code>Realistic Portrait</code> 模型生成的效果：</p><ul><li>高度真实的皮肤质感</li><li>自然的光影过渡</li><li>清晰的五官细节</li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p></p><ul><li>请勿用于商业用途，仅供学习交流</li><li>生成图像需遵守当地法律法规</li><li>建议配合负面提示词使用</li></ul></div><hr><p><a href="/resources/">← 返回创作资源</a></p>`,25)])])}const b=t(r,[["render",o]]);export{p as __pageData,b as default};
